def dims(problem, spend, book, gap, reach, delivery, ids):
    values = [problem, spend, book, gap, reach, delivery]
    keys = ["problem_evidence","spending_evidence","book_format_demand","competitive_gap","reachability","delivery_fit"]
    return {k:{"status":v,"source_ids":ids.get(k,[])} for k,v in zip(keys,values)}


def situation(i, name, buyer, payer, trigger, job, deadline, current, spend, unmet, fit, channel, evidence, decision, reason, origin):
    item={"id":f"RN7R-{i:03d}","name":name,"buyer":buyer,"payer":payer,"purchase_trigger":trigger,"job_to_be_done":job,"deadline":deadline,"current_solution":current,"current_spend":spend,"unmet_need":unmet,"publishing_format_fit":fit,"discovery_channel":channel,"discovery_origin":origin,"evidence_dimensions":evidence,"decision_state":decision,"decision_reason":reason}
    validate_buyer_situation(item)
    return item


